package com.lexorion.payroll.api;import static com.lexorion.payroll.api.CompensationDtos.*;import com.lexorion.payroll.service.CompensationService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/payroll/employees/{employeeCode}/compensation")@PreAuthorize("hasRole('ADMIN')")public class CompensationController{private final CompensationService service;public CompensationController(CompensationService s){service=s;}@GetMapping public List<ProfileResponse>list(@PathVariable String employeeCode){return service.list(employeeCode);}@GetMapping("/{profileKey}")public ProfileResponse get(@PathVariable String employeeCode,@PathVariable String profileKey){return service.get(employeeCode,profileKey);}@PostMapping public ResponseEntity<ProfileResponse>create(@PathVariable String employeeCode,@Valid@RequestBody CreateProfile r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(employeeCode,r));}}
